Here is a concrete Python example of a simple class that manages a list of items:

```python
class ItemManager:
    def __init__(self):
        self.items = []

    def add_item(self, item):
        self.items.append(item)
        print(f"Added: {item}")

    def remove_item(self, item):
        if item in self.items:
            self.items.remove(item)
            print(f"Removed: {item}")
        else:
            print(f"{item} not found in list.")

    def get_items(self):
        return self.items


# Example usage
if __name__ == "__main__":
    manager = ItemManager()
    manager.add_item("apple")
    manager.add_item("banana")
    print(manager.get_items())  # ['apple', 'banana']
    manager.remove_item("apple")
    print(manager.get_items())  # ['banana']
```

